"""Topic catalogs, cases, designs, and behavioral scaffolds.

Answers are interview notes for a synthetic laboratory. They are not a claim
that the reader held a production role.
"""

from __future__ import annotations


def _q(topic: str, prompt: str, answer: str, mistake: str, difficulty: str = "intermediate") -> dict:
    first = answer.split(". ")[0].rstrip(".") + "."
    return {
        "topic": topic,
        "difficulty": difficulty,
        "prompt": prompt,
        "short": first,
        "medium": answer,
        "deep": (
            answer
            + " On a synthetic book I would show the number on a small holdout before arguing for a rollout."
            + " The decision still needs the cost, the capacity, and the failure mode, not only the metric."
        ),
        "follow": [
            "What would you measure next?",
            "Which assumption, if wrong, reverses the recommendation?",
        ],
        "mistake": mistake,
    }


def _bulk(topic: str, rows: list[tuple[str, str, str]], difficulty: str = "intermediate") -> list[dict]:
    return [_q(topic, prompt, answer, mistake, difficulty) for prompt, answer, mistake in rows]


